package validator

import (
	"fmt"
	"reflect"
	"regexp"
	"strings"

	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/util/intstr"
	"k8s.io/apimachinery/pkg/util/validation/field"
)

// deferredFieldIndex is the pre-compiled metadata index (generated by codegen).
// deferredFieldInit ensures thread-safe lazy compilation of the index.

// normalizePath normalizes a field.Path for lookup in deferredFieldIndex.
// It extracts bracketed name segments and finds the longest matching suffix.
// Example: "spec[volumes][0][glusterfs][path]" → ".glusterfs.path" (matches .glusterfs.path)
//          "spec[volumes][0][nfs][path]" → ".nfs.path" (matches .nfs.path)
func normalizePath(p *field.Path) string {
	s := p.String()

	// Strip array indices: [0], [1], etc.
	re := regexp.MustCompile(`\[\d+\]`)
	s = re.ReplaceAllString(s, "")

	// Extract all bracketed name segments: [name] → name
	// e.g. "spec[spec][volumes][glusterfs][endpoints]" → [spec, spec, volumes, glusterfs, endpoints]
	bracketRe := regexp.MustCompile(`\[([^\]]+)\]`)
	matches := bracketRe.FindAllStringSubmatch(s, -1)

	if len(matches) == 0 {
		return s
	}

	// Build suffixes from the end and find the longest matching key
	// e.g. for [glusterfs][endpoints], try: .endpoints → .glusterfs.endpoints
	for i := 0; i < len(matches); i++ {
		// Build suffix from matches[i] to end
		suffixParts := make([]string, len(matches)-i)
		for j := i; j < len(matches); j++ {
			suffixParts[j-i] = matches[j][1]
		}
		key := "." + strings.Join(suffixParts, ".")
		if _, ok := LookupDeferredField(key); ok {
			return key
		}
	}

	// Fallback: return just the last segment
	return "." + matches[len(matches)-1][1]
}

// RunStructuralValidation performs reflection-based validation of a runtime.Object
// using pre-compiled structural metadata. It only inspects deferred fields; Phase 1
// (validatePodSpec) already covers non-deferred fields.
func RunStructuralValidation(obj runtime.Object, basePath *field.Path) field.ErrorList {
	if obj == nil {
		return nil
	}

	var errs field.ErrorList
	visitFields(obj, basePath, func(path *field.Path, meta FieldMetadata, fieldVal reflect.Value) {
		valStr := fieldVal.Interface()
		// Skip unsupported kinds silently; let k8s decode handle them.
		if meta.Type == "" && meta.EnumValues == nil && meta.MinValue == nil && meta.MaxValue == nil {
			// intstr.IntOrString zero-value check: for Required fields of type intstr.Int
			// with IntVal==0, emit field.Required.
			if meta.Required {
				if ios, ok := valStr.(intstr.IntOrString); ok && ios.Type == intstr.Int && ios.IntVal == 0 {
					errs = append(errs, field.Required(path, ""))
				}
				// Nil pointer field with Required:true — emit field.Required.
				if fieldVal.Kind() == reflect.Ptr && fieldVal.IsNil() {
					errs = append(errs, field.Required(path, ""))
				}
			}
			return
		}
		switch meta.Type {
		case "string":
			if s, ok := valStr.(string); ok {
				if s == "" && meta.Required {
					errs = append(errs, field.Required(path, ""))
					return
				}
				if meta.MinLength != nil && len(s) < *meta.MinLength {
					errs = append(errs, field.Invalid(path, s, fmt.Sprintf("min length is %d", *meta.MinLength)))
					return
				}
				if meta.MaxLength != nil && len(s) > *meta.MaxLength {
					errs = append(errs, field.Invalid(path, s, fmt.Sprintf("max length is %d", *meta.MaxLength)))
					return
				}
				if meta.Format == "string" && s != "" {
					// string format validation passed.
				}
				if len(meta.EnumValues) > 0 {
					found := false
					for _, v := range meta.EnumValues {
						if s == v {
							found = true
							break
						}
					}
					if !found {
						errs = append(errs, field.NotSupported(path, s, meta.EnumValues))
					}
				}
			}
		case "integer", "number":
			// Check zero-value for required integer/number fields
			if meta.Required {
				var isZero bool
				switch v := valStr.(type) {
				case int64:
					isZero = v == 0
				case int32:
					isZero = v == 0
				case float64:
					isZero = v == 0
				}
				if isZero {
					errs = append(errs, field.Required(path, ""))
					return
				}
			}
			if meta.MinValue != nil || meta.MaxValue != nil {
				var num float64
				switch v := valStr.(type) {
				case int64:
					num = float64(v)
				case int32:
					num = float64(v)
				case float64:
					num = v
				default:
					return
				}
				if meta.MinValue != nil && num < *meta.MinValue {
					errs = append(errs, field.Invalid(path, num, ""))
				}
				if meta.MaxValue != nil && num > *meta.MaxValue {
					errs = append(errs, field.Invalid(path, num, ""))
				}
			}
		case "boolean":
			// booleans are optional by default; no-op for now.
		case "array":
			// For required arrays, check if the slice is nil or empty.
			if meta.Required {
				rv := reflect.ValueOf(valStr)
				if rv.Kind() == reflect.Slice && rv.Len() == 0 {
					errs = append(errs, field.Required(path, ""))
				}
			}
		}
	})

	return errs
}

// fieldVisitor is called for each leaf field visited during structural validation.
type fieldVisitor func(path *field.Path, meta FieldMetadata, fieldVal reflect.Value)

// visitFields walks the object graph using reflection and calls visitor for each
// deferred field that has a corresponding entry in the metadata index.
func visitFields(obj runtime.Object, basePath *field.Path, visitor fieldVisitor) {
	if obj == nil {
		return
	}

	// Ensure index is initialized (thread-safe, lazy).
	deferredFieldInit.Do(func() {
		if deferredFieldIndex == nil {
			deferredFieldIndex = make(map[string]FieldMetadata)
		}
	})

	objVal := reflect.ValueOf(obj)
	if objVal.Kind() == reflect.Ptr {
		objVal = objVal.Elem()
	}
	if objVal.Kind() != reflect.Struct {
		return
	}

	// Walk all struct fields recursively.
	walkStruct(objVal, basePath, visitor)
}

// walkStruct recursively walks a struct value and invokes the visitor for each field.
func walkStruct(val reflect.Value, path *field.Path, visitor fieldVisitor) {
	if val.Kind() != reflect.Struct {
		return
	}

	typ := val.Type()
	for i := 0; i < typ.NumField(); i++ {
		sf := typ.Field(i)
		fieldVal := val.Field(i)

		if sf.Anonymous && fieldVal.Kind() == reflect.Struct {
			// Recurse into anonymous embedded structs to follow chains
			// like Volume -> VolumeSource -> AzureFile.
			walkStruct(fieldVal, path, visitor)
			continue
		}

		// Construct the JSON-path-like field path from struct field.
		// Use JSON tag name if available (e.g., EndpointsName → endpoints),
		// otherwise fall back to Go field name lowercased (e.g., Path → path).
		jsonTag := sf.Tag.Get("json")
		fieldName := strings.ToLower(sf.Name[:1]) + sf.Name[1:]
		if jsonTag != "" && jsonTag != "-" {
			// JSON tag may be "name,omitempty" — extract just the name part
			if idx := strings.Index(jsonTag, ","); idx >= 0 {
				fieldName = jsonTag[:idx]
			} else {
				fieldName = jsonTag
			}
		}
		fieldPath := path.Key(fieldName)

		// Look up in deferred field index using a normalized path (longest-match
		// suffix so ".glusterfs.path" matches .glusterfs.path, not just .path).
		normalized := normalizePath(fieldPath)
		if meta, ok := LookupDeferredField(normalized); ok {
			visitor(fieldPath, meta, fieldVal)
		}

		// Recurse into nested structs and pointers to structs.
		switch fieldVal.Kind() {
		case reflect.Struct:
			walkStruct(fieldVal, fieldPath, visitor)
		case reflect.Ptr:
			if fieldVal.IsNil() {
				// Emit Required validation for nil pointer fields marked Required
				normalized := normalizePath(fieldPath)
				if meta, ok := LookupDeferredField(normalized); ok && meta.Required {
					visitor(fieldPath, meta, fieldVal)
				}
			} else if fieldVal.Elem().Kind() == reflect.Struct {
				walkStruct(fieldVal.Elem(), fieldPath, visitor)
			}
		case reflect.Slice:
			for j := 0; j < fieldVal.Len(); j++ {
				elem := fieldVal.Index(j)
				if elem.Kind() == reflect.Struct {
					walkStruct(elem, fieldPath.Index(j), visitor)
				}
			}
		}
	}
}